<script setup>
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { forUser } from '../../api'
import { auth,applyProfile } from '../../auth'
import Avatar from './Avatar.vue'
const api=forUser(auth.user?.id)
const props=defineProps({profile:Object}),emit=defineEmits(['saved'])
const pageUserID=auth.user?.id,pageUsername=props.profile.username
let alive=true
onBeforeUnmount(()=>{alive=false})
function receive(p){if(!alive||auth.user?.id!==pageUserID||p.username!==pageUsername||!applyProfile(p,pageUserID))return null;return auth.profile}
const fields=['nickname','bio','avatar_id','daily_questions','daily_minutes','exam_name','exam_date','default_limit','default_module','reading_size','revision']
const editable=p=>Object.fromEntries(fields.map(key=>[key,p[key]]))
const draft=ref(editable(props.profile)),baseline=ref(JSON.stringify(draft.value)),busy=ref(false),error=ref(''),notice=ref(''),conflict=ref(false),errors=ref({}),modules=ref([]),moduleError=ref(''),exportDays=ref('30'),exportBusy=ref(false),exportError=ref('')
function ensureOwner(target=error){if(alive&&auth.user?.id===pageUserID&&!auth.identityChanged)return true;target.value='登录账户已变化，请记录未保存输入后重新进入个人中心';return false}
const dirty=computed(()=>JSON.stringify(draft.value)!==baseline.value)
function reset(profile=props.profile){if(profile.username!==pageUsername||profile.revision<draft.value.revision)return;draft.value=editable(profile);baseline.value=JSON.stringify(draft.value);error.value='';errors.value={};conflict.value=false;notice.value=''}
watch(()=>props.profile,p=>{if(p.revision>=draft.value.revision&&!dirty.value&&JSON.stringify(editable(p))!==baseline.value)reset(p)})
async function loadModules(){moduleError.value='';try{const filters=await api.filters();modules.value=filters.modules || []}catch(e){moduleError.value=e.message}}
loadModules()
function validate(){const e={};for(const [key,max] of [['nickname',40],['bio',200],['exam_name',40]])if(Array.from(draft.value[key]).length>max)e[key]=`最多 ${max} 个字符`;for(const [key,min,max] of [['daily_questions',5,200],['daily_minutes',5,180]])if(!Number.isInteger(draft.value[key])||draft.value[key]<min||draft.value[key]>max)e[key]=`请输入 ${min}–${max} 的整数`;if(draft.value.exam_date&&draft.value.exam_date!==props.profile.exam_date){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const maxDate=new Date(today+'T00:00:00Z');maxDate.setUTCFullYear(maxDate.getUTCFullYear()+5);const maxDay=maxDate.toISOString().slice(0,10);if(draft.value.exam_date<=today||draft.value.exam_date>maxDay)e.exam_date='新设置的日期需为北京时间未来日期，最多五年后'}errors.value=e;return !Object.keys(e).length}
async function save(){if(busy.value||conflict.value)return;error.value='';notice.value='';if(!ensureOwner())return;if(!validate()){error.value='请检查标出的资料字段';return};busy.value=true;try{const saved=await api.saveProfile(editable(draft.value)),confirmed=receive(saved);if(!confirmed)return;reset(confirmed);emit('saved',confirmed);notice.value=confirmed.revision===saved.revision?`资料与偏好已保存 · 版本 ${saved.revision}`:`本次保存已完成（版本 ${saved.revision}），已同步较新资料（版本 ${confirmed.revision}）`}catch(e){error.value=e.status===409&&e.code!=='account_changed'?'资料已在其他窗口更新。本页输入已保留，请先记录，再确认重新加载服务器资料。':e.message;conflict.value=e.status===409&&e.code!=='account_changed'}finally{busy.value=false}}
async function reload(){if(busy.value||!ensureOwner())return;if(!window.confirm('重新加载会放弃本页尚未保存的资料，请先记录本页输入。确定重新加载吗？'))return;busy.value=true;try{const p=receive(await api.profile());if(p){reset(p);emit('saved',p)}}catch(e){error.value=e.message}finally{busy.value=false}}
async function download(){if(exportBusy.value||!ensureOwner(exportError))return;exportBusy.value=true;exportError.value='';try{const blob=await api.exportRecords(exportDays.value);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='行测研习-个人作答记录.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){exportError.value=e.message}finally{exportBusy.value=false}}
defineExpose({dirty,busy,reset})
</script>
<template><div><form class="pc-card pc-profile-form" @submit.prevent="save" novalidate><div class="pc-card-heading"><div><h2>资料与学习偏好</h2><p class="muted small">设置保存到你的学习账户，在其他设备登录也能恢复。</p></div><span class="pc-tag">{{ dirty?'尚未保存':'已同步' }} · 版本 {{ profile.revision }}</span></div><p v-if="error" class="notice err" role="alert">{{ error }}</p><div v-if="conflict" class="notice warn"><button type="button" :disabled="busy" @click="reload">重新加载服务器资料</button><p class="small">重新加载前会再次确认，当前输入不会自动覆盖服务器。</p></div><p v-if="notice" class="notice ok" role="status">{{ notice }}</p><fieldset :disabled="busy"><legend>个人资料</legend><div class="pc-form-grid"><label>用户名<input :value="profile.username" readonly autocomplete="username"/></label><label>昵称<input aria-label="昵称" v-model="draft.nickname" maxlength="80" :aria-invalid="!!errors.nickname" aria-describedby="pc-nickname-hint"/><small class="field-hint" id="pc-nickname-hint">{{ errors.nickname || '最多 40 个字符' }}</small></label><label class="pc-span-two">简介<textarea aria-label="简介" v-model="draft.bio" rows="3" maxlength="400" :aria-invalid="!!errors.bio" aria-describedby="pc-bio-hint"/><small class="field-hint" id="pc-bio-hint">{{ errors.bio || '最多 200 个字符' }}</small></label></div><p class="pc-field-label">头像样式</p><div class="pc-avatar-options" role="group" aria-label="头像样式"><button v-for="id in 8" :key="id" type="button" :aria-label="`头像样式 ${id-1}`" :aria-pressed="draft.avatar_id===id-1" :class="{'pc-avatar-chosen':draft.avatar_id===id-1}" @click="draft.avatar_id=id-1"><Avatar :id="id-1" :name="draft.nickname || profile.username"/><span>{{ id-1 }}</span></button></div></fieldset><fieldset :disabled="busy"><legend>今日目标与考试</legend><div class="pc-form-grid"><label>每日作答目标<input aria-label="每日作答目标" v-model.number="draft.daily_questions" type="number" min="5" max="200" step="1" :aria-invalid="!!errors.daily_questions" aria-describedby="pc-questions-hint"/><small class="field-hint" id="pc-questions-hint">{{ errors.daily_questions || '5–200 次非空作答' }}</small></label><label>每日分钟目标<input aria-label="每日分钟目标" v-model.number="draft.daily_minutes" type="number" min="5" max="180" step="1" :aria-invalid="!!errors.daily_minutes" aria-describedby="pc-minutes-hint"/><small class="field-hint" id="pc-minutes-hint">{{ errors.daily_minutes || '5–180 分钟记录时长' }}</small></label><label>考试名称<input aria-label="考试名称" v-model="draft.exam_name" maxlength="80" :aria-invalid="!!errors.exam_name"/><small class="field-hint">{{ errors.exam_name || '选填，最多 40 个字符' }}</small></label><label>考试日期<input aria-label="考试日期" v-model="draft.exam_date" type="date" :aria-invalid="!!errors.exam_date" aria-describedby="pc-date-hint"/><small class="field-hint" id="pc-date-hint">{{ errors.exam_date || '选填；新日期需为未来且最多五年后。已到期日期可保持原值。' }}</small></label></div></fieldset><fieldset :disabled="busy"><legend>练习偏好</legend><p v-if="moduleError" class="notice err" role="alert">模块加载失败：{{ moduleError }} <button type="button" @click="loadModules">重试</button></p><div class="pc-form-grid"><label>默认题量<select aria-label="默认题量" v-model.number="draft.default_limit"><option :value="10">10 题</option><option :value="20">20 题</option><option :value="50">50 题</option></select></label><label>默认模块<select aria-label="默认模块" v-model="draft.default_module"><option value="">全部模块</option><option v-for="module in modules" :key="module" :value="module">{{ module }}</option><option v-if="draft.default_module&&!modules.includes(draft.default_module)" :value="draft.default_module">{{ draft.default_module }}</option></select><small class="field-hint">题库 URL 中的明确筛选条件优先。</small></label><label>练习正文字号<select aria-label="练习正文字号" v-model.number="draft.reading_size"><option :value="16">标准 · 16px</option><option :value="18">舒适 · 18px</option><option :value="20">大字 · 20px</option></select></label><p class="pc-reading-preview" :style="{fontSize:([16,18,20].includes(draft.reading_size)?draft.reading_size:16)+'px'}">阅读预览：先独立作答，再对照解析。</p></div></fieldset><div class="pc-form-actions"><button class="primary" type="submit" :disabled="busy||conflict">{{ busy?'正在保存…':'保存资料与偏好' }}</button><button type="button" :disabled="busy||!dirty" @click="reload">放弃修改并重载</button><span class="muted small">{{ profile.updated_at ? '最近更新：'+profile.updated_at.slice(0,10) : '' }}</span></div></form><section class="pc-card pc-export"><h2>导出个人作答记录</h2><p class="muted">只包含本人已提交的作答，不包含未提交草稿或题目解析。每次最多 5,000 条，超过时请缩小范围。</p><div class="pc-export-controls"><label>导出范围<select v-model="exportDays"><option value="7">最近 7 天</option><option value="30">最近 30 天</option><option value="90">最近 90 天</option><option value="all">全部记录</option></select></label><button :disabled="exportBusy" @click="download">{{ exportBusy?'正在导出…':'下载 CSV' }}</button></div><p v-if="exportError" class="notice err" role="alert">{{ exportError }}</p></section></div></template>
